INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 24, 'theory', 'Квиз: резервные копии и DR');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 0, 'Что входит в архив, который делает engine-backup?', '["Содержимое дисков всех виртуальных машин", "Снимки виртуальных машин", "База менеджера и файлы его конфигурации", "Образы ISO и шаблоны"]', 2, 'engine-backup защищает сам менеджер: базу и конфигурацию (по желанию и базу DWH). Диски машин лежат на хранилище и требуют отдельной копии.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 1, 'Почему снимок виртуальной машины не заменяет резервную копию?', '["Он лежит на том же хранилище, что и диск, и гибнет вместе с ним", "Он всегда записывается только на ленту", "Он хранит лишь оперативную память", "Его нельзя создать для работающей машины"]', 0, 'Снимок — слой на том же домене, поэтому потеря домена уничтожает и диск, и снимки; к тому же цепочка слоёв растёт и замедляет работу.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 2, 'Что происходит, если битовая карта диска стала недействительной, например после аварийного выключения машины?', '["Копия проходит как обычно", "Менеджер перезаписывает диск", "Хост перезагружается", "Копия завершается ошибкой: недействительную контрольную точку удаляют, и цепочку продолжают с полной копии"]', 3, 'Недействительную карту нельзя определить заранее: она обнаруживается при запуске копии, и копия не проходит. Недействительную контрольную точку удаляют, а цепочку обычно начинают заново с полной копии, иначе при восстановлении данные окажутся повреждены.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 3, 'Когда стоит передавать образ через прокси imageio, а не напрямую на хост?', '["Когда нужна максимальная скорость", "Когда клиент не видит хосты, а доступ есть только к менеджеру", "Когда диск в формате raw", "Когда у машины нет снимков"]', 1, 'Прямой путь быстрее, но требует сетевого доступа к хостам. Прокси на менеджере нужен, когда клиент изолирован и видит только менеджер, ценой скорости.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 24, 4, 'Как менеджер на запасной площадке узнаёт о машинах в подключённом реплицированном домене?', '["Из архива engine-backup основной площадки", "Из OVA-файла каждой машины", "Из описаний в OVF_STORE на самом домене, после чего машины регистрируются", "От virt-v2v"]', 2, 'Описания машин хранятся в служебных дисках OVF_STORE самого домена, поэтому подключённый домен несёт всё нужное для регистрации машин.');
